/** Expand catalogs so each track reaches at least `perTrack` challenges. */
export function buildExpandedCatalog(existing: ChallengeSeed[], perTrack = 100): ChallengeSeed[] {
  const byTrack = new Map<AssessmentTrack, number>();
  const slugs = new Set(existing.map((c) => c.slug));
  for (const c of existing) byTrack.set(c.track, (byTrack.get(c.track) ?? 0) + 1);

  const plans: { track: AssessmentTrack; topics: Topic[] }[] = [
    { track: "SOFTWARE_ENGINEERING", topics: SE_TOPICS },
    { track: "CYBERSECURITY", topics: CYBER_TOPICS },
    { track: "SECURE_FULL_STACK", topics: SFS_TOPICS },
    { track: "PLATFORM_SRE", topics: SRE_TOPICS },
    { track: "DATA_ML", topics: DATA_TOPICS },
    { track: "MOBILE", topics: MOBILE_TOPICS },
    { track: "PRIVACY_ENGINEERING", topics: PRIVACY_TOPICS },
    ...SECTOR_PLANS.map((p) => ({ track: p.track, topics: p.topics as Topic[] })),
  ];

  const generated: ChallengeSeed[] = [];
  for (const plan of plans) {
    const have = byTrack.get(plan.track) ?? 0;
    const fill = Math.max(0, perTrack - have);
    if (fill > 0) {
      generated.push(...buildFromTopics(plan.track, plan.topics, slugs, fill));
    }
  }
  return generated;
}
